import itertools
from scipy.optimize import minimize_scalar
e=df['eps'].values; t=df['T'].values; s=df['sigma'].values
names={'1':np.ones_like(t),'T':t,'T2':t**2,'T3':t**3,'sqrtT':np.sqrt(t),'cosT':np.cos(t),'sinT':np.sin(t),'1/T':1/t,'logT':np.log(t),'expT':np.exp(-t),'T^1.5':t**1.5,'T4':t**4}
def relerr(k,keys):
    h=e*np.exp(-k*e)/t
    A=np.array([names[x] for x in keys]+[h]).T
    c,*_=np.linalg.lstsq(A,s,rcond=None)
    return np.sqrt(np.mean((s-A@c)**2))/np.std(s)
full=list(names.keys())
o=minimize_scalar(lambda k: relerr(k,full),bounds=(0.6,0.9),method='bounded',options={'xatol':1e-10})
print('k full',o.x,o.fun)
kk=o.x
found=[]
keys=list(names.keys())
for r_ in range(3,8):
    for sub in itertools.combinations(keys,r_):
        found.append((relerr(kk,list(sub)),sub))
found.sort(key=lambda x:x[0])
for f_ in found[:8]: print(f_)
